# typed: true
# frozen_string_literal: true

# Handles newsletter-style email subscriptions. A newsletter is
# differentiated by the fact that it isn't content generated by users, but
# rather content generated by GitHub. These types of emails should always have
# unsubscribe links.
#
# Active subscriptions are delivered when next_delivery_at has passed, at
# which point it is incremented by the kind of delivery interval set.
#
# name   - The name of the newsletter for the subscription.
# kind   - The delivery interval for the newsletter.
# active - If this is false, the person has unsubscribed from the newsletter.

class NewsletterSubscription < ApplicationRecord::Domain::Users
  extend T::Sig

  DELIVERY_JOB_SUB_LIMIT = 200

  UNSUBSCRIBE_SCOPE = "NewsletterSubscription:unsubscribe"

  # A list of the different names of newsletters we have in the database.
  # Mostly helpful for maintainence and queries.
  #
  # vulnerability - sends VulnerabilityMailer#digest
  #
  NAMES = %w(vulnerability marketplace_orders)

  # A list of the different intervals newsletters can be delivered for.
  KINDS = %w(daily weekly monthly one_off notification)

  belongs_to :user

  validate :ensure_user_email_exists
  validate :ensure_user_is_not_suspended

  validates_presence_of :kind, :name, :user_id

  # Ensure valid name
  validates_inclusion_of :name, in: NAMES

  # Ensure no double-subscribes
  validates_uniqueness_of :name, scope: :user_id, case_sensitive: false

  # Ensure valid kind
  validates_inclusion_of :kind, in: KINDS

  scope :active, -> { where(active: true) }
  scope :unsubscribed, -> { where(active: false) }

  # Types of newsletters that users can resubscribe to on their own
  scope :allowlisted, -> { where("name IN (?)", NAMES) }

  scope :pending_delivery, ->(type: "vulnerability") { active.where("next_delivery_at <= ? AND name = ?", Time.now.utc, type) }

  # Actually delivers the newsletter. This is usually triggered via
  # deliver_subscriptions. Handles any logic neccecary to find the right
  # mailers or increment the next delivery date.
  #
  # Returns true if the newsletter is saved successfully after processing,
  #   false otherwise
  sig { returns(T::Boolean) }
  def deliver
    return false if already_sent? # Safeguard
    return false unless self.user
    success = T.let(false, T::Boolean)

    GitHub::CurrentTenant.set(T.must(self.user).enterprise_managed_business) do
      unless self.valid?
        GitHub.logger.info(
          "Newsletter could not be delivered",
          "gh.security_alerts.newsletter.stage": :invalid,
          "gh.user.id": T.must(user).id,
          "gh.user.login": T.must(user).login,
          "gh.security_alerts.newsletter.subscription_name": self.name,
          "gh.security_alerts.newsletter.subscription_period": self.kind,
        )

        ActiveRecord::Base.connected_to(role: :writing) do
          # if it's not valid, let's turn it off
          self.update_column(:active, false)
        end
        return false
      end

      success = record_delivery!

      case name
      when "vulnerability"
        GitHub.dogstats.distribution_time("vulnerability.mailer.digest_distribution") do
          digests = VulnerabilityMailerManager.new(self.user, self.kind).generate_digests
          digests.each do |mail|
            GitHub.dogstats.distribution_time("vulnerability.mailer.digest_deliver_distribution") do
              mail.deliver_now
            end
          end
        end
      end
    end
    success
  end

  # Have we already sent this subscription? This is used as a safegaurd to
  # ensure we never send the same subscription twice at once.
  #
  # Returns a boolean.
  sig { returns(T::Boolean) }
  def already_sent?
    return false if sent_at.nil?
    T.must(sent_at) >= next_delivery_at
  end

  # Public: Creates a new instance of a newsletter subscription.
  #
  # user - who is subscribing to the newsletter
  # name - The name of the newsletter, like 'explore'
  # kind - A field to describe the logic of this newsletter. Ex: 'weekly' or
  #        'non-technical'
  # resubscribe - (boolean:optional) whether to resubscribe a user who was
  #               previously subscribed to the newsletter
  # auto_subscribed - (boolean:optional) sets the 'auto_subscribe' column on the subscription to
  #                   indicate if user was auto subscribed to the newsletter.
  #
  # Returns a new NewsletterSubscription
  sig do
    params(
      user: User,
      name: String,
      kind: String,
      resubscribe: T::Boolean,
      auto_subscribed: T::Boolean,
    ).returns(NewsletterSubscription)
  end
  def self.subscribe(user, name, kind, resubscribe: true, auto_subscribed: false)

    if subscription = where("user_id = ? AND name = ?", user.id, name).first
      # user was previously subscribed, so just return existing subscription and change nothing
      return subscription if !resubscribe
      subscription.kind = kind
    else
      subscription = user.newsletter_subscriptions.build(
        name: name,
        kind: kind)
    end

    name_tag = %w[explore vulnerability].include?(name) ? name : nil
    kind_tag = %w[daily weekly monthly].include?(kind) ? kind : nil

    tags = ["name:#{name_tag}", "kind:#{kind_tag}"]

    if !subscription.active?
      GitHub.dogstats.increment("newsletter_subscription.resubscribe", tags: tags)
    end
    subscription.auto_subscribed = auto_subscribed
    subscription.schedule_next_delivery
    subscription.subscribed_at = Time.current
    subscription.active = true
    subscription.save!

    GitHub.logger.info(
      "Newsletter subscription successful",
      "gh.security_alerts.newsletter.stage": :subscription,
      "gh.user.id": user.id,
      "gh.user.login": user.login,
      "gh.security_alerts.newsletter.subscription_name": name,
      "gh.security_alerts.newsletter.subscription_period": kind,
    )
    GitHub.dogstats.increment("newsletter_subscription.subscribe", tags: tags)

    subscription
  end

  # Public: Unsubscribes the user from the newsletter
  #
  # token - the token for the newsletter
  #
  sig { params(token: String).returns(T.nilable(NewsletterSubscription)) }
  def self.unsubscribe(token)
    token = self.validate_token(token)

    return nil unless token

    if subscription = where("user_id = ? AND name = ?", token.user.id, token.data["name"]).first
      subscription.update! active: false
      subscription
    end
  end

  # Public: Unsubscribe user from all their currently
  # subscribed newsletters.
  #
  # user - User instance
  #
  # Returns a Boolean.
  sig { params(user: User).returns(Integer) }
  def self.unsubscribe_all(user)
    GitHub.dogstats.distribution_time("newsletter_subscription.unsubscribe_all_distribution") do
      user.newsletter_subscriptions.active.update_all(active: false)
    end
  end

  # Public: the GitHub::Authentication::SignedAuthToken for the given token value
  #
  # token - the token to validate
  #
  sig { params(token: String).returns(T.nilable(GitHub::Authentication::SignedAuthToken)) }
  def self.validate_token(token)
    token = User.verify_signed_auth_token token: token,
                                          scope: UNSUBSCRIBE_SCOPE
    token unless token.reason != :valid
  end

  # Public: Human readable name that can be presented to the user.
  # Returns a String.
  sig { returns(String) }
  def human_name
    name
  end

  # Public: Generate an unsubscribe token.
  #
  # Returns the string for the unsubscribe token
  def unsubscribe_token
    self.class.get_unsubscribe_token user, name
  end

  # Public: Generate the unsubscribe token for the user/name.
  #
  # user - who is subscribing to the newsletter
  # name - the classname of the mailer (eg. 'explore')
  #
  # Returns the string for the unsubscribe token
  def self.get_unsubscribe_token(user, name)
    user.signed_auth_token scope: UNSUBSCRIBE_SCOPE,
                           expires: 1.year.from_now,
                           data: { "name" => name }
  end

  # Kicks off a delivery run. This method is safe to call at any time of day.
  #
  # Returns true if a new delivery run was started.
  sig { params(type: String).returns(T::Boolean) }
  def self.start_delivery(type:)
    total_count = 0
    # fetch ids in batches of 100,000
    self.pending_delivery(type: type).in_batches(of: DELIVERY_JOB_SUB_LIMIT * 500) do |batch|
      ids = batch.pluck(:id)

      break if ids.empty?
      total_count += ids.size

      # this will enqueue as many jobs as is necessary to process and deliver all subscriptions
      # in chunks of DELIVERY_JOB_SUB_LIMIT subscriptions
      ids.in_groups_of(DELIVERY_JOB_SUB_LIMIT) do |sub_ids|
        GitHub.dogstats.increment("newsletter_subscription.delivery.job_count", tags: ["type:#{type}"])

        NewsletterDeliveryRunJob.perform_later(sub_ids)
      end
    end

    if total_count > 0
      # report how many subscriptions were enqueded
      GitHub.dogstats.count("newsletter_subscription.delivery.subscription_count", total_count, tags: ["type:#{type}"])
      true
    else
      false
    end
  end

  sig { returns(T::Boolean) }
  def pending_delivery?
    active? && T.must(next_delivery_at) <= Time.now.utc
  end

  # Delivers a newsletter to a user. This method is designed to be run inside
  # of N jobs to deliver newsletters. It will pull from subscriptions that
  # need to be delivered until there are no more that need to be delivered.
  #
  # Returns nothing.
  sig { params(sub_ids: T::Array[Integer]).void }
  def self.deliver_subscriptions(sub_ids:)
    subs = self.where(id: sub_ids).joins(:user).where("users.suspended_at is null")
    subs.each do |sub|
      begin
        next unless sub.pending_delivery?

        sub.deliver

        GitHub.dogstats.increment("newsletter.delivery.success", tags: ["name:#{sub.name}", "kind:#{sub.kind}"])
      rescue => boom # rubocop:todo Lint/GenericRescue
        Failbot.report(boom, newsletter_subscription_id: sub.id)
        GitHub.dogstats.increment("newsletter.delivery.error", tags: ["name:#{sub.name}", "kind:#{sub.kind}", "error:#{boom.class}"])
      end
    end
  end

  # Internal: Schedule the next delivery for a
  # newsletter based on its individual delivery requirements.
  sig { void }
  def schedule_next_delivery
    klass = case name
    when "vulnerability"
      VulnerabilityMailer
    end
    return unless klass
    self.next_delivery_at = klass.next_delivery_for(user, kind)
  end

  # Public: Reactivate an existing subscription.
  #
  # Returns a Boolean.
  sig { returns(T::Boolean) }
  def resubscribe
    return true if active?
    GitHub.dogstats.increment("newsletter_subscription.resubscribe", tags: ["name:#{name}", "kind:#{kind}"])
    schedule_next_delivery
    update! active: true, subscribed_at: Time.current
  end

  # Public: Deactivate a subscription.
  #
  # Returns a Boolean.
  sig { returns(T::Boolean) }
  def unsubscribe
    return true if !active?
    GitHub.dogstats.increment("newsletter_subscription.unsubscribe", tags: ["name:#{name}", "kind:#{kind}"])
    update! active: false
  end

  private

  sig { returns(T::Boolean) }
  def record_delivery!
    schedule_next_delivery

    self.active = false if kind == "one_off"
    self.delivery_count = T.must(self.delivery_count) + 1
    self.sent_at = Time.current
    success = ActiveRecord::Base.connected_to(role: :writing) do
      throttle do
        save!
      end
    end

    GitHub.logger.info(
      "Newsletter delivery successful",
      "gh.security_alerts.newsletter.stage": :delivery,
      "gh.user.id": T.must(user).id,
      "gh.user.login": T.must(user).login,
      "gh.security_alerts.newsletter.subscription_name": name,
      "gh.security_alerts.newsletter.subscription_period": kind,
    )

    success
  end

  sig { void }
  def ensure_user_email_exists
    if T.must(user).primary_user_email.nil?
      errors.add(:user, "requires primary email")
    end
  end

  sig { void }
  def ensure_user_is_not_suspended
    if T.must(user).suspended?
      errors.add(:user, "is suspended")
    end
  end
end
